cond_t cv = COND_INIT();
int food_ready = 0;

void Philosopher(int id) {
  mutex_lock(&lk);
  while (!food_ready) {
    cond_wait(&cv, &lk);
  }
  printf("Philosopher %d is eating!\n", id);
  mutex_unlock(&lk);
}

void Waiter() {
  mutex_lock(&lk);
  food_ready = 1;
  cond_broadcast(&cv);
  mutex_unlock(&lk);
} 当然当然，偶尔有的时候，有一两年，我会出一个你用信号量可以做得很简单的并发编程。你可以选择稳妥起见安全地拿 20 分，用万能的同步方法，你也可以相信自己的这个实力，然后去写一个这个很聪明的并发并发控制。

